const MODS=DATA.modules, ALLQ=MODS.flatMap(m=>m.questions), QB=new Map(ALLQ.map(q=>[q.id,q])), TERMS=MODS.flatMap(m=>m.terms.map((t,i)=>({...t,id:m.id+'t'+i,module:m.id}))), TM=new Map(TERMS.map(t=>[t.id,t]));
