const obj=x=>x!==null&&typeof x==='object'&&!Array.isArray(x), finite=(x,lo,hi)=>typeof x==='number'&&Number.isFinite(x)&&x>=lo&&x<=hi, txt=(x,n=120)=>typeof x==='string'?x.replace(/[\u0000-\u001f\u007f]/g,' ').slice(0,n):'', clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
function rng(seed){let s=seed>>>0;return()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};}
function shuffle(a,r){a=a.slice();for(let i=a.length-1;i>0;i--){let j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function questions(key,seed){const r=rng(seed);if(MODIDS.has(key))return shuffle(MODS.find(m=>m.id===key).questions,r);if(key!=='final')return[];let out=MODS.map(m=>m.questions[Math.floor(r()*m.questions.length)]);for(const m of shuffle(MODS,r).slice(0,8)){const rest=m.questions.filter(q=>!out.some(o=>o.id===q.id));out.push(rest[Math.floor(r()*rest.length)]);}return shuffle(out,r);}
function number(s){if(typeof s!=='string'&&typeof s!=='number')return null;const t=String(s).trim().replace(/−/g,'-');if(!/^[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?$/.test(t))return null;const n=Number(t);return Number.isFinite(n)?n:null;}
function response(q,a){if(q.type==='mc')return Number.isInteger(a)&&a>=0&&a<q.options.length?a:null;if(q.type==='ms')return Array.isArray(a)?[...new Set(a.filter(x=>Number.isInteger(x)&&x>=0&&x<q.options.length))].sort((a,b)=>a-b):[];return typeof a==='string'?txt(a,50):finite(a,-1e12,1e12)?String(a):null;}
function grade(q,a){a=response(q,a);if(q.type==='mc')return a===q.answer?1:0;if(q.type==='ms'){let good=new Set(q.answer),C=good.size,I=q.options.length-C;if(!C)return 0;let tp=a.filter(x=>good.has(x)).length,fp=a.length-tp;return clamp(I?tp/C-fp/I:tp/C,0,1);}let n=number(a);return n!==null&&Math.abs(n-q.answer)<=q.tol+1e-12?1:0;}
function answered(q,a){a=response(q,a);return q.type==='ms'?a.length>0:q.type==='num'?number(a)!==null:a!==null;}
function stamp(x){return typeof x==='string'&&x.length<=40&&Number.isFinite(Date.parse(x))?new Date(x).toISOString():null;}
function blank(){return {schema:'ai101-progress',schemaVersion:1,courseId:CFG.id,courseVersion:CFG.version,created:new Date().toISOString(),profile:{name:'',sid:''},settings:{theme:'system',instructor:'',institution:''},lessons:{},attempts:{},drafts:{},cards:{},project:{topic:'',decision:'',data:'',split:'',baseline:'',checks:'',limits:'',disclosure:''},view:'#/home'};}
function scoreAttempt(key,seed,answers,ts=new Date().toISOString()){let qs=questions(key,seed),points=qs.map(q=>grade(q,answers[q.id]));return {seed,ts,answers:Object.fromEntries(qs.map(q=>[q.id,response(q,answers[q.id])])),score:100*points.reduce((s,p)=>s+p,0)/qs.length};}
function normalize(o){if(!obj(o)||o.schema!=='ai101-progress'||o.schemaVersion!==1||o.courseId!==CFG.id)throw Error('This is not a supported AI 101 progress export.');const p=blank();p.created=stamp(o.created)||p.created;if(obj(o.profile)){p.profile={name:txt(o.profile.name,80),sid:txt(o.profile.sid,40)};}if(obj(o.settings)){p.settings={theme:['system','light','dark'].includes(o.settings.theme)?o.settings.theme:'system',instructor:txt(o.settings.instructor,120),institution:txt(o.settings.institution,120)};}if(obj(o.lessons))for(const k of LESSONS)if(o.lessons[k]===true)p.lessons[k]=true;
for(const key of [...MODIDS,'final']){if(obj(o.attempts)&&Array.isArray(o.attempts[key])){let a=o.attempts[key].filter(x=>obj(x)&&Number.isInteger(x.seed)&&finite(x.seed,0,4294967295)&&stamp(x.ts)&&obj(x.answers)).map(x=>scoreAttempt(key,x.seed,x.answers,stamp(x.ts)));if(a.length>200){const best=a.reduce((b,x)=>x.score>b.score?x:b);a=a.slice(-199);if(!a.includes(best))a.unshift(best);}p.attempts[key]=a;}if(obj(o.drafts)&&obj(o.drafts[key])){let d=o.drafts[key];if(Number.isInteger(d.seed)&&finite(d.seed,0,4294967295)&&obj(d.answers))p.drafts[key]={seed:d.seed,answers:Object.fromEntries(questions(key,d.seed).map(q=>[q.id,response(q,d.answers[q.id])]))};}}
if(obj(o.cards))for(const t of TERMS){const c=o.cards[t.id];if(obj(c))p.cards[t.id]={step:Number.isInteger(c.step)?clamp(c.step,-1,4):-1,due:finite(c.due,0,1e15)?c.due:0,reps:Number.isInteger(c.reps)?clamp(c.reps,0,1e6):0};}if(obj(o.project))for(const k in p.project)p.project[k]=txt(o.project[k],4000);p.view=route(o.view).hash;return p;}
function best(p,key){let a=p.attempts[key]||[];return a.length?Math.max(...a.map(x=>x.score)):null;}
function grading(p){const scores=MODS.map(m=>best(p,m.id)),avg=scores.reduce((s,v)=>s+(v??0),0)/MODS.length,f=best(p,'final'),overall=.7*avg+.3*(f??0);return {scores,avg,final:f,overall,band:overall>=90?'Distinction':overall>=80?'Merit':overall>=70?'Pass':'Not yet completed',eligible:scores.every(x=>x!==null&&x>=70)&&f!==null&&f>=70};}
function route(hash){let h=typeof hash==='string'?hash:'';let a=h.match(/^#\/m\/(\d{1,2})(?:\/(\d|quiz|cards|review))?$/);if(a){let n=+a[1],sub=a[2]||'1';if(n>=1&&n<=16&&['1','2','3','quiz','cards','review'].includes(sub))return {type:'module',n,sub,hash:`#/m/${n}/${sub}`};}if(/^#\/(home|glossary|cards|labs|project|final|progress|data|settings|certificate|sources)$/.test(h))return {type:h.slice(2),hash:h};return {type:'home',hash:'#/home'};}
