function boot(){document.querySelector('.skip').onclick=e=>{e.preventDefault();$('#main').focus();};try{localStorage.setItem(KEY+'-probe','1');localStorage.removeItem(KEY+'-probe');storageOK=true;let raw=localStorage.getItem(KEY);if(raw)P=normalize(JSON.parse(raw));}catch(e){if(storageOK){message('Saved data could not be restored safely; a blank session was opened. Import a valid backup.');}else storageOK=false;}storageBanner();theme();let outline=$('#outline');for(let m of MODS)outline.append(E('a',{href:`#/m/${m.num}/1`,'data-n':m.num,text:String(m.num).padStart(2,'0')+' · '+m.title}));$('#theme').onclick=()=>{let a=['system','light','dark'];P.settings.theme=a[(a.indexOf(P.settings.theme)+1)%3];theme();save();};$('#export').onclick=()=>download('AI_101_progress.json',JSON.stringify(P,null,2),'application/json');window.addEventListener('hashchange',()=>{render();save();$('#main').focus();window.scrollTo({top:0,behavior:'auto'});});if(!location.hash)history.replaceState(null,'',P.view);render();}
